import java.io.IOException;

public class ReadLoop {
    public static void main(String[] args) throws IOException {
        String s = "";
        int c = 0;
        while (c != '\n') {
            c = System.in.read();
            s += (char) c;
        }
        System.out.println(s.length());
    }
}
